// Test rapide de la connexion au démarrage sans bloquer le serveur
async function verifierConnexionRapide() {
  const allowInMemory = process.env.ALLOW_IN_MEMORY === "true" && process.env.NODE_ENV !== "production";

  try {
    const client = await pool.connect();
    await client.query("SELECT 1");
    client.release();
    isDbConnected = true;
    derniereTentativeEchouee = 0;
    console.log("[PostgreSQL] Connecté avec succès à la base de données.");
    if (!isTestEnv) {
      autoMigrerSchema().catch(() => {});
    }
  } catch (err) {
    isDbConnected = false;
    derniereTentativeEchouee = Date.now();

    // Journalisation structurée de l'erreur
    console.error(
      JSON.stringify({
        timestamp: new Date().toISOString(),
        niveau: "CRITICAL",
        composant: "database-pool",
        message: "PostgreSQL est inaccessible au démarrage",
        erreur: err.message,
        code: err.code || "DB_CONNECTION_FAILED",
        allowInMemory,
        environnement: process.env.NODE_ENV || "development",
      })
    );

    // Envoi d'une alerte via telemetrieService
    try {
      const telemetrieService = require("../services/telemetrie.service");
      telemetrieService
        .enregistrerErreur({
          source: "database-startup",
          typeErreur: "PostgresConnectionFailed",
          message: `Échec de connexion PostgreSQL critique : ${err.message}`,
          niveau: "critical",
        })
        .catch(() => {});
    } catch (_) {}

    // Règle 3 : Le mode In-Memory ne doit exister qu'en développement et en test,
    // activé explicitement par ALLOW_IN_MEMORY=true.
    // En production, si PostgreSQL est injoignable, le serveur refuse de démarrer.
    if (!allowInMemory) {
      console.error(
        "[PostgreSQL ARRÊT DU SERVEUR] En production ou sans ALLOW_IN_MEMORY=true, " +
          "le serveur refuse de démarrer sans base de données PostgreSQL joignable."
      );
      if (process.env.NODE_ENV === "production") {
        process.exit(1);
      }
    } else {
      console.warn("[PostgreSQL Mode Résilient] Base injoignable -> ALLOW_IN_MEMORY activé en dev/test.");
    }
  }
}

// Lancement de la première vérification
verifierConnexionRapide().catch(() => {});

// Interception de pool.query pour un repli ultra-rapide (< 0.1ms) si DB hors-ligne confirmée
const originalQuery = pool.query.bind(pool);
pool.query = async function (text, params) {
  const allowInMemory = process.env.ALLOW_IN_MEMORY === "true" && process.env.NODE_ENV !== "production";

  // Si une tentative précédente a échoué il y a moins de 30 secondes, basculer sans attendre
  if (
    !isDbConnected &&
    derniereTentativeEchouee > 0 &&
    Date.now() - derniereTentativeEchouee < DELAI_REVERIFICATION_MS
  ) {
    if (!allowInMemory) {
      throw new Error("DB_OFFLINE: Base de données PostgreSQL inaccessible (mode In-Memory désactivé).");
    }
    throw new Error("DB_OFFLINE: Base de données distante temporairement inaccessible");
  }

  try {
    const res = await originalQuery(text, params);
    isDbConnected = true;
    derniereTentativeEchouee = 0;
    return res;
  } catch (err) {
    const msg = (err && err.message) || "";
    if (
      msg.includes("ENOTFOUND") ||
      msg.includes("ECONNREFUSED") ||
      msg.includes("ETIMEDOUT") ||
      msg.includes("not found") ||
      msg.includes("timeout") ||
      msg.includes("tenant")
    ) {
      isDbConnected = false;
      derniereTentativeEchouee = Date.now();
    }
    throw err;
  }
};

/**
 * Exécute `travail(client)` à l'intérieur d'une transaction SQL.
 * Si la base est hors-ligne, fournit un client fictif mémoire uniquement si ALLOW_IN_MEMORY est activé.
 */
async function avecTransaction(travail) {
  const allowInMemory = process.env.ALLOW_IN_MEMORY === "true" && process.env.NODE_ENV !== "production";

  if (!isDbConnected && Date.now() - derniereTentativeEchouee < DELAI_REVERIFICATION_MS) {
    if (!allowInMemory) {
      throw new Error("DB_OFFLINE: Base de données inaccessible pour transaction.");
    }
    const mockClient = {
      query: async (sql, params) => {
        return { rows: [], rowCount: 0 };
      },
    };
    return await travail(mockClient);
  }

  let client;
  try {
    client = await pool.connect();
  } catch (errConnect) {
    isDbConnected = false;
    derniereTentativeEchouee = Date.now();
    if (!allowInMemory) {
      throw errConnect;
    }
    const mockClient = {
      query: async () => ({ rows: [], rowCount: 0 }),
    };
    return await travail(mockClient);
  }

  try {
    await client.query("BEGIN");
    const resultat = await travail(client);
    await client.query("COMMIT");
    isDbConnected = true;
    return resultat;
  } catch (erreur) {
    try {
      await client.query("ROLLBACK");
    } catch (_) {}
    throw erreur;
  } finally {
    if (client) client.release();
  }
}

function estEnLigne() {
  return isDbConnected;
}

module.exports = { pool, avecTransaction, estEnLigne, verifierConnexionRapide };

/**
 * src/middleware/controlHubAuth.middleware.js
 *
 * Middleware de sécurité pour l'API Interne (/api/internal/*).
 * Authentifie les requêtes provenant du SaaS de Contrôle Centralisé (Master Super Admin Hub)
 * via la clé secrète partagée CONTROL_HUB_SECRET_KEY.
 */

const crypto = require("crypto");

function exigerCleControlHub(req, res, next) {
  const secretAttendu = process.env.CONTROL_HUB_SECRET_KEY;

  if (!secretAttendu || !secretAttendu.trim()) {
    console.error(
      "[ControlHubAuth] Erreur de configuration : CONTROL_HUB_SECRET_KEY n'est pas définie sur ce serveur."
    );
    return res.status(500).json({
      erreur: "Erreur de configuration serveur : Clé de contrôle interne non configurée.",
    });
  }

  // 1. Récupération de la clé fournie (via header custom ou Authorization Bearer)
  let secretFourni = req.headers["x-control-hub-secret"] || "";

  if (!secretFourni) {
    const authHeader = req.headers["authorization"] || "";
    if (authHeader.startsWith("Bearer ")) {
      secretFourni = authHeader.slice(7).trim();
    }
  }

  if (!secretFourni || typeof secretFourni !== "string") {
    return res.status(401).json({
      erreur: "Accès refusé : En-tête 'x-control-hub-secret' ou 'Authorization: Bearer' requis pour l'API interne.",
    });
  }

  // 2. Comparaison en temps constant (Timing Safe Equal) pour éviter les attaques temporelles
  try {
    const bufAttendu = Buffer.from(secretAttendu, "utf8");
    const bufFourni = Buffer.from(secretFourni, "utf8");

    if (bufAttendu.length !== bufFourni.length || !crypto.timingSafeEqual(bufAttendu, bufFourni)) {
      return res.status(401).json({
        erreur: "Accès refusé : Clé secrète de contrôle interne invalide.",
      });
    }
  } catch (err) {
    return res.status(401).json({
      erreur: "Accès refusé : Échec de validation de la clé de contrôle.",
    });
  }

  // Clé valide : on poursuit
  req.estControlHub = true;
  next();
}

module.exports = { exigerCleControlHub };

