  if (Array.isArray(sauvegardes)) {
    for (const u of sauvegardes) {
      if (u && u.email) {
        const norm = u.email.toLowerCase().trim();
        UTILISATEURS_MEMOIRE.set(u.id, { ...u, email: norm });
