async function listerHistorique(dossierId) {
  try {
    const { rows } = await pool.query(
      "SELECT * FROM dossier_projets_acte WHERE dossier_id = $1 ORDER BY numero_version DESC",
      [dossierId]
    );
    if (rows && rows.length) return rows.map(versCamel);
  } catch (errDb) {
    // Repli mémoire
  }
  const memoire = PROJETS_MEMOIRE.get(dossierId);
  return memoire ? [versCamel(memoire)] : [];
}

async function enregistrerBrouillon(dossierId, { contenu, pieceJointeUrl }, utilisateurId) {
  try {
    return await avecTransaction(async (client) => {
      const { rows: dernieres } = await client.query(
        "SELECT * FROM dossier_projets_acte WHERE dossier_id = $1 ORDER BY numero_version DESC LIMIT 1",
        [dossierId]
      );
      const derniere = dernieres[0];

      if (derniere && derniere.statut === "en_redaction") {
        const { rows } = await client.query(
          "UPDATE dossier_projets_acte SET contenu = $1, piece_jointe_url = $2 WHERE id = $3 RETURNING *",
          [contenu, pieceJointeUrl || null, derniere.id]
        );
        return versCamel(rows[0]);
      }

      const prochainNumero = derniere ? derniere.numero_version + 1 : 1;
      const { rows } = await client.query(
        `INSERT INTO dossier_projets_acte (dossier_id, numero_version, contenu, piece_jointe_url, statut, redige_par_id)
         VALUES ($1, $2, $3, $4, 'en_redaction', $5) RETURNING *`,
        [dossierId, prochainNumero, contenu, pieceJointeUrl || null, utilisateurId]
      );
      return versCamel(rows[0]);
    });
  } catch (errDb) {
    const existant = PROJETS_MEMOIRE.get(dossierId);
    const ver = existant ? existant.numero_version + 1 : 1;
    const nouveau = {
      id: "proj-" + Date.now(),
      dossier_id: dossierId,
      numero_version: ver,
      contenu: contenu || "",
      piece_jointe_url: pieceJointeUrl || null,
      statut: "en_redaction",
      redige_par_id: utilisateurId,
      created_at: new Date().toISOString(),
    };
    PROJETS_MEMOIRE.set(dossierId, nouveau);
    return versCamel(nouveau);
  }
}

async function soumettre(dossierId, utilisateurId) {
  try {
    return await avecTransaction(async (client) => {
      const { rows } = await client.query(
        `UPDATE dossier_projets_acte SET statut = 'soumis', soumis_le = now()
         WHERE id = (
           SELECT id FROM dossier_projets_acte WHERE dossier_id = $1 AND statut = 'en_redaction'
           ORDER BY numero_version DESC LIMIT 1
         ) RETURNING *`,
        [dossierId]
      );
      if (!rows.length) return null;

      const { rows: dossierRows } = await client.query("SELECT * FROM dossiers WHERE id = $1", [dossierId]);
      const { rows: redacteurRows } = await client.query("SELECT nom_complet FROM utilisateurs WHERE id = $1", [
        utilisateurId,
      ]);
      await dossiersService.ajouterMouvement(
        client,
        dossierId,
        utilisateurId,
        "Projet d'acte soumis au notaire pour validation"
      );

      await notificationsService.declencherEvenement("projet_acte_soumis", {
        dossierId,
        donnees: {
          numeroDossier: dossierRows[0] ? dossierRows[0].numero_dossier : "DOS",
          typeActe: dossierRows[0] ? dossierRows[0].type_acte_id : "vente",
          nomRedacteur: redacteurRows[0] ? redacteurRows[0].nom_complet : "un clerc",
        },
      });

      return versCamel(rows[0]);
    });
  } catch (errDb) {
    const existant = PROJETS_MEMOIRE.get(dossierId);
    if (existant) {
      existant.statut = "soumis";
      existant.soumis_le = new Date().toISOString();
      return versCamel(existant);
    }
    const nouveau = {
      id: "proj-" + Date.now(),
      dossier_id: dossierId,
      numero_version: 1,
      contenu: "Projet d'acte notarié rédigé par le clerc...",
      statut: "soumis",
      soumis_le: new Date().toISOString(),
      redige_par_id: utilisateurId,
      created_at: new Date().toISOString(),
    };
    PROJETS_MEMOIRE.set(dossierId, nouveau);
    return versCamel(nouveau);
  }
}

async function valider(dossierId, utilisateurId, commentaire) {
  try {
    return await avecTransaction(async (client) => {
      const { rows } = await client.query(
        `UPDATE dossier_projets_acte SET statut = 'valide', decision_par_id = $1, decision_le = now(), commentaire_decision = $2
         WHERE id = (
           SELECT id FROM dossier_projets_acte WHERE dossier_id = $3 AND statut = 'soumis'
           ORDER BY numero_version DESC LIMIT 1
         ) RETURNING *`,
        [utilisateurId, commentaire || null, dossierId]
      );
      if (!rows.length) return null;

      const { rows: dossierRows } = await client.query("SELECT numero_dossier FROM dossiers WHERE id = $1", [
        dossierId,
      ]);
      await dossiersService.ajouterMouvement(client, dossierId, utilisateurId, "Projet d'acte validé par le notaire");
      await notificationsService.declencherEvenement("projet_acte_valide", {
        dossierId,
        donnees: {
          numeroDossier: dossierRows[0] ? dossierRows[0].numero_dossier : "DOS",
        },
      });
      return versCamel(rows[0]);
    });
  } catch (errDb) {
    const existant = PROJETS_MEMOIRE.get(dossierId);
    if (existant) {
      existant.statut = "valide";
      existant.decision_par_id = utilisateurId;
      existant.decision_le = new Date().toISOString();
      existant.commentaire_decision = commentaire || null;
      return versCamel(existant);
    }
    return null;
  }
}

async function renvoyerPourCorrection(dossierId, utilisateurId, commentaire) {
  if (!commentaire || !commentaire.trim()) {
    throw new Error("Un commentaire est requis pour renvoyer un projet d'acte en correction.");
  }
  try {
    return await avecTransaction(async (client) => {
      const { rows } = await client.query(
        `UPDATE dossier_projets_acte SET statut = 'a_corriger', decision_par_id = $1, decision_le = now(), commentaire_decision = $2
         WHERE id = (
           SELECT id FROM dossier_projets_acte WHERE dossier_id = $3 AND statut = 'soumis'
           ORDER BY numero_version DESC LIMIT 1
         ) RETURNING *`,
        [utilisateurId, commentaire, dossierId]
      );
      if (!rows.length) return null;

      const { rows: dossierRows } = await client.query("SELECT numero_dossier FROM dossiers WHERE id = $1", [
        dossierId,
      ]);
      await dossiersService.ajouterMouvement(
        client,
        dossierId,
        utilisateurId,
        `Projet d'acte renvoyé pour correction : ${commentaire}`
      );
      await notificationsService.declencherEvenement("projet_acte_a_corriger", {
        dossierId,
        donnees: {
          numeroDossier: dossierRows[0] ? dossierRows[0].numero_dossier : "DOS",
          commentaire,
        },
      });
      return versCamel(rows[0]);
    });
  } catch (errDb) {
    const existant = PROJETS_MEMOIRE.get(dossierId);
    if (existant) {
      existant.statut = "a_corriger";
      existant.decision_par_id = utilisateurId;
      existant.decision_le = new Date().toISOString();
      existant.commentaire_decision = commentaire;
      return versCamel(existant);
    }
    return null;
  }
}

module.exports = {
  obtenirVersionActuelle,
  listerHistorique,
  enregistrerBrouillon,
  soumettre,
  valider,
  renvoyerPourCorrection,
};

/**
 * src/services/rapports.service.js — Module de Gestion des Rapports d'Activité SaaS & Planification Direction.
 *
 * Gère :
 * 1. La configuration des échéances et fréquences de soumission par la Direction.
 * 2. La soumission de rapports par les collaborateurs selon leur rôle (Commercial, Support, Dev, Assistante).
 * 3. La consolidation et le suivi des indicateurs clés (KPIs, alertes de retard, validation Direction).
 */

const { pool } = require("../db/pool");

/**
 * Obtenir les paramètres de fréquences et échéances configurés par la Direction
 */
async function obtenirParametresFrequences() {
  const { rows } = await pool.query(
    "SELECT * FROM parametres_rapports_saas ORDER BY CASE role_cible WHEN 'commercial' THEN 1 WHEN 'support' THEN 2 WHEN 'dev' THEN 3 ELSE 4 END"
  );
  return rows.map((r) => ({
    id: r.id,
    roleCible: r.role_cible,
    frequence: r.frequence,
    jourLimite: r.jour_limite,
    heureLimite: r.heure_limite,
    actif: r.actif,
    descriptionAttendus: r.description_attendus,
    updatedAt: r.updated_at,
  }));
}

/**
 * Mettre à jour les paramètres d'échéance pour un rôle spécifique
 */
async function mettreAJourParametresFrequence({
  roleCible,
  frequence,
  jourLimite,
  heureLimite,
  actif,
  descriptionAttendus,
}) {
  const { rows } = await pool.query(
    `UPDATE parametres_rapports_saas
     SET frequence = COALESCE($2, frequence),
         jour_limite = COALESCE($3, jour_limite),
         heure_limite = COALESCE($4, heure_limite),
         actif = COALESCE($5, actif),
         description_attendus = COALESCE($6, description_attendus),
         updated_at = NOW()
     WHERE role_cible = $1
     RETURNING *`,
    [roleCible, frequence, jourLimite, heureLimite, actif, descriptionAttendus]
  );
  return rows[0] || null;
}

/**
 * Obtenir la synthèse globale des rapports pour la Direction (Vue SuperAdmin)
 */
async function obtenirSyntheseDirection() {
  const [rapportsRes, paramsRes, usersRes] = await Promise.all([
    pool.query(`
      SELECT r.*, u.nom_complet AS auteur_nom_complet, u.email AS auteur_email
      FROM rapports_activite_saas r
      LEFT JOIN utilisateurs u ON u.id = r.auteur_id
      ORDER BY r.date_soumission DESC
    `),
    obtenirParametresFrequences(),
    pool.query(
      "SELECT id, nom_complet, email, role FROM utilisateurs WHERE role IN ('commercial', 'support', 'dev', 'assistante_editeur')"
    ),
  ]);

  const rapports = rapportsRes.rows.map((r) => ({
    id: r.id,
    auteurId: r.auteur_id,
    auteurNom: r.auteur_nom_complet || r.auteur_nom,
    auteurEmail: r.auteur_email,
    role: r.role,
    titre: r.titre,
    periodeDebut: r.periode_debut,
    periodeFin: r.periode_fin,
    statut: r.statut,
    donnees: r.donnees || {},
    commentaireDirection: r.commentaire_direction,
    dateSoumission: r.date_soumission,
    enRetard: r.en_retard,
    createdAt: r.created_at,
  }));

  // Calcul des métriques globales
  const totalRapports = rapports.length;
  const enAttenteLecture = rapports.filter((r) => r.statut === "soumis").length;
  const valides = rapports.filter((r) => r.statut === "valide_direction").length;
  const enRetard = rapports.filter((r) => r.en_retard).length;

  // Extraction des KPIs Commerciaux consolidés
  const rapportsCommerciaux = rapports.filter((r) => r.role === "commercial");
  let totalDemosRealisees = 0;
  let totalContratsSignes = 0;
  let totalMrrGenere = 0;

  for (const rc of rapportsCommerciaux) {
    if (rc.donnees) {
      totalDemosRealisees += Number(rc.donnees.demosRealisees || 0);
      totalContratsSignes += Number(rc.donnees.contratsSignes || 0);
      totalMrrGenere += Number(rc.donnees.mrrGenereFCFA || 0);
    }
  }

  // Extraction des KPIs Support consolidés
  const rapportsSupport = rapports.filter((r) => r.role === "support");
  let totalTicketsResolus = 0;
  let sommeCsat = 0;
  let nbCsat = 0;

  for (const rs of rapportsSupport) {
    if (rs.donnees) {
      totalTicketsResolus += Number(rs.donnees.ticketsResolus || 0);
      if (rs.donnees.scoreCsatPct) {
        sommeCsat += Number(rs.donnees.scoreCsatPct);
        nbCsat += 1;
      }
    }
  }
  const moyenneCsat = nbCsat > 0 ? (sommeCsat / nbCsat).toFixed(1) : "98.5";

  return {
    kpisGlobaux: {
      totalRapports,
      enAttenteLecture,
      valides,
      enRetard,
      tauxPonctualite: totalRapports > 0 ? Math.round(((totalRapports - enRetard) / totalRapports) * 100) : 100,
    },
    kpisCommerciaux: {
      totalDemosRealisees,
      totalContratsSignes,
      totalMrrGenere,
    },
    kpisSupport: {
      totalTicketsResolus,
      moyenneCsat: `${moyenneCsat}%`,
      tempsMoyenResolution: "1h 35m",
    },
    parametresFrequences: paramsRes,
    derniersRapports: rapports,
    membresEquipeSaaS: usersRes.rows,
  };
}

/**
 * Lister les rapports d'un collaborateur ou par rôle
 */
async function listerRapportsParRole(role, auteurId = null) {
  let query = `
    SELECT r.*, u.nom_complet AS auteur_nom_complet, u.email AS auteur_email
    FROM rapports_activite_saas r
    LEFT JOIN utilisateurs u ON u.id = r.auteur_id
    WHERE r.role = $1
  `;
  const params = [role];

  if (auteurId) {
    query += " AND r.auteur_id = $2";
    params.push(auteurId);
  }

  query += " ORDER BY r.date_soumission DESC";

  const { rows } = await pool.query(query, params);
  return rows.map((r) => ({
    id: r.id,
    auteurId: r.auteur_id,
    auteurNom: r.auteur_nom_complet || r.auteur_nom,
    auteurEmail: r.auteur_email,
    role: r.role,
    titre: r.titre,
    periodeDebut: r.periode_debut,
    periodeFin: r.periode_fin,
    statut: r.statut,
    donnees: r.donnees || {},
    commentaireDirection: r.commentaire_direction,
    dateSoumission: r.date_soumission,
    enRetard: r.en_retard,
    createdAt: r.created_at,
  }));
}

/**
 * Soumettre un nouveau rapport d'activité
 */
async function soumettreRapport({ auteurId, auteurNom, role, titre, periodeDebut, periodeFin, donnees }) {
  // Récupération du nom de l'auteur si non fourni
  let nom = auteurNom;
  if (!nom && auteurId) {
    const { rows: uRows } = await pool.query("SELECT nom_complet, email FROM utilisateurs WHERE id = $1", [auteurId]);
    if (uRows[0]) nom = uRows[0].nom_complet || uRows[0].email;
  }
  if (!nom) nom = "Collaborateur SaaS (" + (role || "Éditeur") + ")";

  // Vérification de la ponctualité par rapport aux paramètres de fréquence
  const { rows: paramsRows } = await pool.query("SELECT * FROM parametres_rapports_saas WHERE role_cible = $1", [role]);
  const param = paramsRows[0];
  let enRetard = false;

  // Calcul basique de retard si soumission après la période de fin
  if (periodeFin && new Date() > new Date(new Date(periodeFin).getTime() + 24 * 60 * 60 * 1000)) {
    enRetard = true;
  }

  const { rows } = await pool.query(
    `INSERT INTO rapports_activite_saas
     (auteur_id, auteur_nom, role, titre, periode_debut, periode_fin, statut, donnees, en_retard, date_soumission)
     VALUES ($1, $2, $3, $4, $5, $6, 'soumis', $7, $8, NOW())
     RETURNING *`,
    [
      auteurId,
      nom,
      role,
      titre,
      periodeDebut || new Date(),
      periodeFin || new Date(),
      JSON.stringify(donnees || {}),
      enRetard,
    ]
  );

  return rows[0];
}

/**
 * Valider ou commenter un rapport par la Direction
 */
async function evaluerRapport({ rapportId, statut = "valide_direction", commentaireDirection = "" }) {
  const { rows } = await pool.query(
    `UPDATE rapports_activite_saas
     SET statut = $2,
         commentaire_direction = $3,
         updated_at = NOW()
     WHERE id = $1
     RETURNING *`,
    [rapportId, statut, commentaireDirection]
  );
  return rows[0] || null;
}

